svg.script:
var armedLabel = "";
var captureSent = false;

function setText(id, value) {
  var node = document.getElementById(id);
  if (node && node.firstChild) node.firstChild.data = value;
}

function pollState() {
  try {
    var xhr = new XMLHttpRequest();
    xhr.onreadystatechange = function() {
      if (xhr.readyState != 4) return;
      if (xhr.status == 200) {
        try {
          var frame = document.getElementById("stateFrame");
          frame.setAttributeNS("http://www.w3.org/1999/xlink", "href", "/remote-map/frame.svg?t=" + new Date().getTime());
          var fields = xhr.responseText.split("|");
          var stateStatus = fields[0];
          var stateLabel = fields[1];
          if (stateStatus == "armed") {
            armedLabel = stateLabel;
            captureSent = false;
            setText("prompt", stateLabel);
            setText("result", "Press exactly one button");
            setText("status", "ARMED");
          } else if (stateStatus == "captured") {
            armedLabel = "";
            setText("prompt", stateLabel);
            setText("result", "CAPTURED: " + fields[2] + " / " + fields[3]);
            setText("status", "Recorded — waiting for next terminal prompt");
          } else {
            armedLabel = "";
            setText("prompt", "WAITING FOR TERMINAL");
            setText("result", "No button armed");
          }
        } catch(e) {}
      }
      window.setTimeout(pollState, 250);
    };
    xhr.open("GET", "http://191.32.31.251/remote-map/state?format=text&t=" + new Date().getTime(), true);
    xhr.send();
  } catch(e) {
    window.setTimeout(pollState, 1000);
  }
}

function captureKey(evt) {
  if (!armedLabel || captureSent || evt.type != "keydown") return;
  captureSent = true;
  var code = evt.keyCode || evt.which || 0;
  setText("result", "SENDING CODE " + code + "...");
  try {
    var xhr = new XMLHttpRequest();
    xhr.open("GET", "http://191.32.31.251/remote-map/capture?code=" + code, true);
    xhr.send();
  } catch(e) {
    captureSent = false;
  }
}

try { document.addEventListener("keydown", captureKey, false); } catch(e) {}
try { document.documentElement.focus(); } catch(e) {}
try {
  var ready = new XMLHttpRequest();
  ready.open("GET", "http://191.32.31.251/remote-map/ready?t=" + new Date().getTime(), true);
  ready.send();
} catch(e) {}
pollState();
